// THE DATABASE MAP IS COMPLETE AND CURRENT (it_engineer, 10 Nov 2026).
//
// docs/architecture/database/ files every routine, table, view, cron job and edge function production runs under one
// business area, with the canonical SQL file of each routine and the seat that owns each cron job. It is generated by
// scripts/architecture/database_map.mjs. A map that is allowed to fall behind is worse than none: an auditor would trust
// it. So this fails when
//   * a name is in no area (a new routine whose words no rule knows: add a word or an OVERRIDES line), or
//   * a page differs from what the generator writes now (a routine added, dropped, or moved to a new canonical file
//     without regenerating), or a page exists that no area generates.
// Fix either by running `node scripts/architecture/database_map.mjs` and committing docs/architecture/database/.
//
// The two refusals are proved below on a synthetic name and a copy of the pages, so this check is seen to bite.
//   node --test scripts/checks/the_database_map_is_complete_and_current.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { buildMap, renderPages, checkMap } from '../architecture/database_map.mjs';
import { areaOf } from '../architecture/database_areas.mjs';

const map = buildMap();
const rendered = renderPages(map);

test('every routine, table, view, cron job and edge function is in an area, and every page is current', () => {
  assert.deepEqual(checkMap(undefined, rendered), []);
});

test('the map covers what the mirror holds: thousands of routines, hundreds of tables, every cron job owned', () => {
  // Floors, not exact counts: an exact count would fail on every apply. They catch a parser that silently reads nothing.
  assert.ok(map.routines.length > 1500, `routines read: ${map.routines.length}`);
  assert.ok(map.tables.length > 500, `tables read: ${map.tables.length}`);
  assert.ok(map.crons.length > 50, `cron jobs read: ${map.crons.length}`);
  assert.equal(map.routines.filter((r) => !r.file).length, 0, 'a routine production runs with no canonical file');
  const unowned = map.crons.filter((c) => !c.seat).map((c) => c.jobname);
  assert.deepEqual(unowned, [], 'cron jobs whose owning seat no committed file records');
});

test('BITES: a routine whose words no rule knows is reported UNMAPPED', () => {
  const name = 'fn_zq_wxv_qqq';
  assert.equal(areaOf(name), null);
  const r = renderPages({ ...map, routines: [...map.routines, { name, overloads: 1, file: null, area: areaOf(name) }] });
  assert.ok(r.unmapped.includes(name));
  assert.ok(checkMap(undefined, r).some((p) => p.startsWith(`UNMAPPED  ${name}`)));
});

test('BITES: a stale page, a missing page and an extra page are each reported', () => {
  const dir = mkdtempSync(join(tmpdir(), 'database-map-'));
  try {
    const [first, ...rest] = [...rendered.pages];
    writeFileSync(join(dir, first[0]), first[1] + '\nhand edit\n');
    for (const [name, text] of rest.slice(1)) writeFileSync(join(dir, name), text);
    writeFileSync(join(dir, 'retired-area.md'), 'old');
    const problems = checkMap(dir, rendered);
    assert.ok(problems.some((p) => p.startsWith('STALE') && p.endsWith(first[0])), problems.join('\n'));
    assert.ok(problems.some((p) => p.startsWith('MISSING') && p.endsWith(rest[0][0])), problems.join('\n'));
    assert.ok(problems.some((p) => p.startsWith('EXTRA') && p.includes('retired-area.md')), problems.join('\n'));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
